import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'app-regulator-section',
  templateUrl: './regulator-section.page.html',
  styleUrls: ['./regulator-section.page.scss'],
})
export class RegulatorSectionPage implements OnInit {

  inspectionHeader = [
    { name: "Establishment Details", id: 1, value: "1" },
    { name: "Renewal Details", id: 2, value: "1" },
    { name: "Student Strength Details", id: 3, value: "1" },
    { name: "Staff Details", id: 4, value: "1" },
    { name: "Land Details", id: 5, value: "1" },
    { name: "Infrastructure Details", id: 6, value: "1" },
    { name: "Fund Details", id: 7, value: "1" },
    { name: "Endowment Fund", id: 8, value: "2" },
    { name: "Corpus Fund", id: 9, value: "2" },
    { name: "Management Contribution", id: 10, value: "2" },
    { name: "Inspection Fee", id: 11, value: "2" },
    { name: "Previous order", id: 12, value: "1" },
    { name: "Details of previous order", id: 13, value: "2" },
    { name: "Conditions", id: 14, value: "2" },
    { name: "Application Fee", id: 15, value: "1" }
  ]

  uidse: any;
  routeData: any;
  status: any;
  schoolid: any;

  constructor(private route: ActivatedRoute,
    private router: Router,) { }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.routeData = this.route.snapshot;
    this.status = this.routeData.queryParams.status;
    this.uidse = this.routeData.queryParams.uidse;
    this.schoolid = this.routeData.queryParams.id;
    parseInt(this.status); 
  }

  nextPage(value) {

    if (value == '1') {
      this.router.navigate(['/tabs/establishment'], {
        queryParams: { status: value, "uidse": this.uidse }, skipLocationChange: false
      });
    }

    if (value == '2') {
      this.router.navigate(['/tabs/renewal-details'], {
        queryParams: { status: 2, "uidse": this.uidse }, skipLocationChange: false
      });
    }

    if (value == '3') {
      this.router.navigate(['/tabs/student-details'], {
        queryParams: { status: 3, "uidse": this.uidse }, skipLocationChange: false
      });
    }

    if (value == '4') {
      this.router.navigate(['/tabs/staff-details'], {
        queryParams: { status: 5, "uidse": this.uidse }, skipLocationChange: false
      });
    }

    if (value == '5') {
      this.router.navigate(['/tabs/land-details'], {
        queryParams: { status: 5, "uidse": this.uidse }, skipLocationChange: false
      });
     }

    if (value == '6') {
      this.router.navigate(['/tabs/building-classification'], { queryParams: { 'schoolId': this.schoolid, 'udise': this.uidse, "addbuildingCount": "new" }, skipLocationChange: false });
    }

    // if (value == '6') {
    //   this.router.navigate(['/tabs/endowment-fund'], {
    //     queryParams: { status: 6, "uidse": this.uidse }, skipLocationChange: false
    //   });
    // }

    if (value == '7') {
      // this.router.navigate(['/tabs/endowment-fund'], {
      //   queryParams: { status: 7, "uidse": this.uidse }, skipLocationChange: false
      // }); 
    }

    if (value == '8') {
      this.router.navigate(['/tabs/endowment-fund'], {
        queryParams: { status: 8, "uidse": 'Endowment Fund' }, skipLocationChange: false
      });
    }

    if (value == '9') {
      this.router.navigate(['/tabs/endowment-fund'], {
        queryParams: { status: 9, "uidse": 'Corpus Fund' }, skipLocationChange: false
      });
    }

    if (value == '10') {
      this.router.navigate(['/tabs/endowment-fund'], {
        queryParams: { status: 10, "uidse": 'Management Contribution' }, skipLocationChange: false
      });
    }

    if (value == '11') {
      this.router.navigate(['/tabs/endowment-fund'], {
        queryParams: { status: 11, "uidse": 'Inspection Fee' }, skipLocationChange: false
      });
    }

    if (value == '12') {
    }

    if (value == '13') {
      this.router.navigate(['/tabs/endowment-fund'], {
        queryParams: { status: 13, "uidse": 'Details of previous order' }, skipLocationChange: false
      });
    }

    if (value == '14') {
      this.router.navigate(['/tabs/endowment-fund'], {
        queryParams: { status: 14, "uidse": 'Conditions' }, skipLocationChange: false
      });
    }

    if (value == '15') {
      this.router.navigate(['/tabs/endowment-fund'], {
        queryParams: { status: 15, "uidse": 'Application Fee' }, skipLocationChange: false
      });
    }

  }

  onNextPage() {
    this.router.navigate(['/tabs/inspection']);
  }

}
